    const d = sai.body().data;
    pm.expect(Object.keys(d).sort()).to.eql(["allowedFormats", "apiKey", "cloudName", "expiresAt", "folder", "maxBytes", "mediaId", "publicId", "resourceType", "signature", "timestamp", "type", "uploadParams"]);
