    pm.expect(minutes).to.be.within(55, 61);
});

pm.test("signature is the SHA-1 of the sorted signed params plus the API secret (server-decided params only)", () => {
    const secret = pm.variables.get("cloudinaryApiSecret");
    if (!secret) return;
    const d = sai.body().data;
    const params = { allowed_formats: d.allowedFormats, folder: d.folder, public_id: d.publicId, timestamp: d.timestamp, type: d.type };
    const toSign = Object.keys(params).sort().map((k) => k + "=" + params[k]).join("&");
    pm.expect(d.signature).to.eql(CryptoJS.SHA1(toSign + secret).toString());
});

