(function (pm) {
    "use strict";
    // Shared helpers for every script of this collection. Stored once in the collection variable `saiLib` and loaded
    // with: const sai = eval(pm.collectionVariables.get("saiLib"))(pm);
    const UNSAFE = ["POST", "PUT", "PATCH", "DELETE"];
    const TAGS = [
        "session", "pending", "pwd", "reset", "acct", "email", "del", "media", "learner",
        "profile", "rl", "lock", "e2e", "err", "other", "avatar", "utf8", "cap",
    ];
    const v = (name) => pm.variables.get(name);
    const setVar = (name, value) => pm.collectionVariables.set(name, value);
    const unsetVar = (name) => pm.collectionVariables.unset(name);
    const baseUrl = () => String(v("baseUrl"));
    const prefix = () => String(v("apiPrefix"));
    const apiUrl = (path) => baseUrl() + prefix() + path;
    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
    const jar = () => pm.cookies.jar();
    const parseJson = (text) => { try { return JSON.parse(text); } catch (e) { return undefined; } };
    const body = () => parseJson(pm.response.text());
    const header = (name) => pm.response.headers.get(name);

    // ---- run identity -------------------------------------------------------------------------------------------
    const randomText = (length) => {
        const chars = "abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";
        let out = "";
        for (let i = 0; i < length; i += 1) out += chars[Math.floor(Math.random() * chars.length)];
        return out;
    };
    const strongPassword = () => "Zq" + randomText(8) + "-" + randomText(6) + "!7";

    function startRun() {
        const runId = Date.now().toString(36) + randomText(4).toLowerCase();
        setVar("runId", runId);
        const domain = String(v("allowedEmailDomain") || "example.test");
        TAGS.forEach((tag) => setVar(tag + "Email", "sai-" + runId + "-" + tag + "@" + domain));
        setVar("userName", "Postman Runner");
        setVar("password", strongPassword());
        setVar("newPassword", strongPassword());
        setVar("thirdPassword", strongPassword());
        setVar("adminNewPassword", strongPassword());
        setVar("weakPassword", "short1!");
        setVar("longPassword", "Aa1!" + "x".repeat(72));
        setVar("commonPassword", "password1234");
        setVar("invalidToken", randomText(43));
        setVar("longToken", randomText(600));
        setVar("fakeCredential", "not-a-real-id-token-" + randomText(12));
        setVar("unknownObjectId", "64b64b64b64b64b64b64b64b");
        setVar("badObjectId", "not-an-object-id");
        setVar("disallowedEmail", "sai-" + runId + "@other.test");
        setVar("sessionEmailUpper", ("sai-" + runId + "-session@" + domain).toUpperCase());
        const fullwidth = (text) => text.replace(/[a-z0-9]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0xfee0));
        setVar("sessionEmailFullwidth", fullwidth("sai") + "-" + fullwidth(runId) + "-" + fullwidth("session") + "@" + domain);
        setVar("bytes72Password", "Aa1!" + "é".repeat(34));
        setVar("bytes73Password", "Aa1!" + "é".repeat(34) + "x");
        setVar("emailNamePassword", "Xx-sai-" + runId + "-err-9!");
        setVar("longName", "N".repeat(101));
        setVar("adminLoginPassword", String(v("adminPassword") || ""));
        setVar("newAddress", "sai-" + runId + "-newaddress@" + domain);
        ["neutralRegister", "neutralForgot", "neutralResend", "neutralChangeEmail", "verifyToken", "resetToken",
            "confirmToken", "undoToken", "sessionId", "otherSessionId", "mediaId", "mediaPublicId", "pdfMediaId",
            "webmMediaId", "rotatedAt", "lockRetryAfter", "lockMessage", "invalidCredentialsMessage", "staleVerifyToken", "foreignSessionId",
            "sessionToRevoke", "adminLimited", "firstSessionId", "avatarPublicId", "tempMediaId", "superMediaId", "superPublicId", "moderatedMediaId", "moderatedPublicId", "undoToken", "confirmToken"].forEach((name) => unsetVar(name));
    }
    function ensureRun() { if (!v("runId")) startRun(); }

    // ---- cookies and CSRF ---------------------------------------------------------------------------------------
    const cookieValue = (name, path) => new Promise((resolve) => {
        jar().get(baseUrl() + (path || "/"), name, (e, c) => resolve(c && typeof c === "object" ? c.value : c || undefined));
    });
    const dropCookie = (name, path) => new Promise((resolve) => {
        jar().unset(baseUrl() + (path || "/"), name, () => resolve());
    });
    const putCookie = (name, value, path, httpOnly) => new Promise((resolve) => {
        jar().set(baseUrl() + (path || "/"), { name, value, path: path || "/", httpOnly: !!httpOnly }, () => resolve());
    });
    const refreshPath = () => prefix() + "/auth/refresh";
    const refreshCookiePath = () => prefix() + "/auth";
    const forgetSession = async () => {
        await dropCookie("sai_access");
        await dropCookie("sai_refresh", refreshPath());
    };
    const prime = () => new Promise((resolve) => pm.sendRequest({ url: apiUrl("/auth/me"), method: "GET" }, () => resolve()));
    async function ensureCsrf() {
        let value = await cookieValue("sai_csrf");
        if (!value) { await prime(); value = await cookieValue("sai_csrf"); }
        return value;
    }
    async function syncCsrf() {
        if (!UNSAFE.includes(pm.request.method)) return;
        const value = await ensureCsrf();
        if (value) pm.request.headers.upsert({ key: "X-CSRF-Token", value });
    }
    const dropCsrfHeader = () => pm.request.headers.remove("X-CSRF-Token");
    const setCsrfHeader = (value) => pm.request.headers.upsert({ key: "X-CSRF-Token", value });
    const slowRequest = (factor) => pm.variables.set("budgetFactor", factor || 4);

    // ---- side requests (share the cookie jar) -------------------------------------------------------------------
    // TEST-41: outside the local test server only the read-only Smoke folder may run (and prod never sends an unsafe method).
    const kind = () => String(v("environmentKind") || "local");
    const inSmoke = () => pm.execution.location.indexOf("Smoke") >= 0;
    function skipUnlessLocal() {
        if (kind() === "local" || inSmoke()) return false;
        pm.execution.skipRequest();
        return true;
    }
    async function side(method, path, payload, extraHeaders) {
        if (kind() !== "local") throw new Error("side requests are only allowed against the local test server (environmentKind=local)");
        const headers = Object.assign({ "Content-Type": "application/json" }, extraHeaders || {});
        if (UNSAFE.includes(method) && !headers["X-CSRF-Token"]) headers["X-CSRF-Token"] = (await ensureCsrf()) || "";
        const options = { url: apiUrl(path), method, header: headers };
        if (payload !== undefined) options.body = { mode: "raw", raw: typeof payload === "string" ? payload : JSON.stringify(payload) };
        return new Promise((resolve) => pm.sendRequest(options, (err, res) => {
            resolve({ err, res, code: res ? res.code : undefined, json: () => (res ? parseJson(res.text()) : undefined) });
        }));
    }
    async function login(emailVar, passwordVar) {
        return side("POST", "/auth/login", { email: v(emailVar), password: v(passwordVar || "password") });
    }

    // Repeats a cheap request until the limiter answers 429; returns the attempt number that was refused (0 = never).
    async function exhaust(method, path, payload, maxTries) {
        for (let i = 1; i <= maxTries; i += 1) {
            const answer = await side(method, path, payload);
            if (answer.code === 429) return i;
        }
        return 0;
    }

    // ---- test-only mail outbox ----------------------------------------------------------------------------------
    const outboxPath = (filter) => "/__test__/outbox?" + Object.keys(filter).map((k) => k + "=" + encodeURIComponent(filter[k])).join("&");
    async function mails(filter) {
        const r = await side("GET", outboxPath(filter));
        const data = r.json();
        return data && data.data && Array.isArray(data.data.emails) ? data.data.emails : [];
    }
    async function waitForMail(filter, opts) {
        const wanted = (opts && opts.count) || 1;
        const until = Date.now() + ((opts && opts.timeoutMs) || 5000);
        for (;;) {
            const found = await mails(filter);
            if (found.length >= wanted || Date.now() > until) return found;
            await sleep(30);
        }
    }
    const quietMails = async (filter, quietMs) => { await sleep(quietMs || 400); return mails(filter); };
    const lastToken = (found) => (found.length ? found[found.length - 1].token : undefined);

    // ---- assertions ---------------------------------------------------------------------------------------------
    const SUCCESS_SCHEMA = {
        type: "object",
        required: ["statusCode", "success", "message", "data"],
        properties: {
            statusCode: { type: "integer" },
            success: { const: true },
            message: { type: "string", minLength: 1 },
            data: {},
            meta: { type: "object" },
        },
        additionalProperties: false,
    };
    const ERROR_SCHEMA = {
        type: "object",
        required: ["statusCode", "success", "message", "code", "errors", "data", "requestId"],
        properties: {
            statusCode: { type: "integer" },
            success: { const: false },
            message: { type: "string", minLength: 1 },
            code: { type: "string", pattern: "^[A-Z][A-Z0-9_]+$" },
            errors: {
                type: "array",
                items: {
                    type: "object",
                    required: ["message"],
                    properties: { field: { type: "string" }, message: { type: "string" }, code: { type: "string" } },
                    additionalProperties: false,
                },
            },
            data: { type: "null" },
            requestId: { type: "string", minLength: 8 },
            retryAfterSec: { type: "integer" },
        },
        additionalProperties: false,
    };
    const USER_KEYS = ["authProviders", "avatar", "email", "emailVerified", "hasPassword", "id", "locale",
        "mustChangePassword", "name", "orgId", "role", "status"];

    const status = (code) => pm.test("status is " + code, () => pm.response.to.have.status(code));
    const jsonContent = () => pm.test("Content-Type is application/json", () => {
        pm.expect(header("Content-Type") || "").to.match(/^application\/json/);
    });
    function ok(code, message) {
        status(code);
        jsonContent();
        pm.test("success envelope { statusCode, success, message, data }", () => {
            pm.response.to.have.jsonSchema(SUCCESS_SCHEMA);
            const b = body();
            pm.expect(b.statusCode).to.eql(code);
            pm.expect(b).to.have.property("data");
            if (message) pm.expect(b.message).to.eql(message);
        });
    }
    function fail(code, errCode, opts) {
        const o = opts || {};
        status(code);
        jsonContent();
