            pm.response.to.have.jsonSchema(ERROR_SCHEMA);
            const b = body();
            pm.expect(b.statusCode).to.eql(code);
            pm.expect(b.code).to.eql(errCode);
            pm.expect(b).to.not.have.property("stack");
        });
