    // ---- cookies in the response --------------------------------------------------------------------------------
    const parseSetCookie = (line) => {
        const parts = String(line).split(";").map((s) => s.trim());
        const first = parts[0];
        const at = first.indexOf("=");
        const attrs = {};
        parts.slice(1).forEach((p) => {
            const i = p.indexOf("=");
            attrs[(i < 0 ? p : p.slice(0, i)).toLowerCase()] = i < 0 ? true : p.slice(i + 1);
        });
        return { name: first.slice(0, at), value: first.slice(at + 1), attrs };
    };
    const setCookies = () => pm.response.headers
        .filter((h) => String(h.key).toLowerCase() === "set-cookie")
        .map((h) => parseSetCookie(h.value));
    const secureExpected = () => String(v("expectSecureCookies")) === "true";
    function universalCookieFlags() {
        const mine = setCookies().filter((c) => c.name.indexOf("sai_") === 0);
        if (mine.length === 0) return;
        pm.test("sai_* cookies: HttpOnly (csrf not), SameSite=Lax, Path, Secure per environment", () => {
            mine.forEach((c) => {
                pm.expect(!!c.attrs.httponly, c.name + " HttpOnly").to.eql(c.name !== "sai_csrf");
                pm.expect(String(c.attrs.samesite).toLowerCase(), c.name + " SameSite").to.eql("lax");
                pm.expect(c.attrs.path, c.name + " Path").to.eql(c.name === "sai_refresh" ? prefix() + "/auth" : "/");
                pm.expect(!!c.attrs.secure, c.name + " Secure").to.eql(secureExpected());
            });
        });
        pm.test("no cookie value is repeated in the body", () => {
            const text = pm.response.text();
            mine.filter((c) => c.value.length > 8).forEach((c) => pm.expect(text.indexOf(c.value), c.name).to.eql(-1));
        });
    }
    // spec: { set: { sai_access: 900, ... }, cleared: [names], absent: [names] }
    function cookies(spec) {
        const found = {};
        setCookies().forEach((c) => { found[c.name] = c; });
        Object.keys(spec.set || {}).forEach((name) => {
            pm.test(name + " is set with Max-Age " + spec.set[name], () => {
                pm.expect(found[name], name + " Set-Cookie").to.exist;
                pm.expect(found[name].value).to.not.eql("");
                pm.expect(Number(found[name].attrs["max-age"])).to.eql(spec.set[name]);
            });
        });
        (spec.cleared || []).forEach((name) => {
            pm.test(name + " is cleared with the same attributes", () => {
                pm.expect(found[name], name + " Set-Cookie").to.exist;
                pm.expect(found[name].value).to.eql("");
                pm.expect(new Date(found[name].attrs.expires).getTime()).to.be.below(Date.now());
            });
        });
        (spec.absent || []).forEach((name) => {
