    const fullSession = (remember) => cookies({
        set: {
            sai_access: SESSION.access,
            sai_refresh: remember ? SESSION.remember : SESSION.normal,
            sai_csrf: remember ? SESSION.remember : SESSION.normal,
        },
    });

    // ---- helpers for scripts ------------------------------------------------------------------------------------
    function checkMailLink(mail, route) {
        pm.test("mail link uses the #token= fragment on " + route + ", never a query string", () => {
            pm.expect(mail.links.length, "links").to.be.above(0);
            const link = mail.links[0];
            pm.expect(link).to.match(new RegExp("^https?://[^/]+" + route + "#token="));
            pm.expect(link.indexOf("?")).to.eql(-1);
            pm.expect(mail.token).to.be.a("string").with.length.above(20);
        });
    }
