                pm.expect(text).to.not.match(/eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/);
                ["password", "newPassword", "thirdPassword", "adminPassword", "adminNewPassword", "cloudinaryApiSecret"].forEach((name) => {
